const items = $input.all();

// Find the real answer text, skipping any "thinking" blocks
function getText(item) {
  const j = item.json;
  if (Array.isArray(j.content)) {
    const blocks = j.content.filter(b => b.type === 'text' && b.text);
    if (blocks.length) return blocks.map(b => b.text).join('\n');
  }
  if (j.content && Array.isArray(j.content.parts)) {
    return j.content.parts.map(p => p.text || '').join('\n');
  }
  if (Array.isArray(j.candidates)) {
    return (j.candidates[0]?.content?.parts || []).map(p => p.text || '').join('\n');
  }
  let t = j.text ?? j.output ?? '';
  if (typeof t !== 'string') t = JSON.stringify(t);
  return t;
}

// Pull the JSON object out of the text, even if there is extra wording around it
function parseJson(t) {
  const clean = t.replace(/```json|```/g, '').trim();
  try {
    return JSON.parse(clean);
  } catch (e) {
    const start = clean.indexOf('{');
    const end = clean.lastIndexOf('}');
    if (start !== -1 && end > start) {
      try { return JSON.parse(clean.slice(start, end + 1)); } catch (e2) {}
    }
    return { parse_error: true, raw: t };
  }
}

// Identify each result by what it contains, not by its position
let content = null;
let formatting = null;
for (const item of items) {
  const parsed = parseJson(getText(item));
  if (parsed.category_scores || parsed.overall_score !== undefined) content = parsed;
  else if (parsed.formatting_score !== undefined || parsed.mandatory) formatting = parsed;
  else if (!content) content = parsed;
  else formatting = parsed;
}
content = content || { parse_error: true, raw: '' };
formatting = formatting || { parse_error: true, raw: '' };

// Recalculate the overall score so arithmetic mistakes can't slip through
if (Array.isArray(content.category_scores)) {
  content.overall_score = content.category_scores.reduce(
    (sum, c) => sum + Number(c.score || 0), 0
  );
}

const fs = Number(formatting.formatting_score);
const hasMustFix =
  (Array.isArray(formatting.critical_issues) && formatting.critical_issues.length > 0) ||
  (formatting.mandatory && Array.isArray(formatting.mandatory.failed) && formatting.mandatory.failed.length > 0);

if (hasMustFix) {
  formatting.final_verdict = 'NEEDS IMPROVEMENTS';
} else if (!isNaN(fs)) {
  formatting.final_verdict = fs >= 8 ? 'PASS' : fs >= 6 ? 'COULD BE BETTER' : 'NEEDS IMPROVEMENTS';
}
const form = $('Webhook').first().json.body;

return [{
  json: {
    status: 'done',
    role: form.target_role,
    experience_level: form.experience_level,
    content_audit: content,
    formatting_audit: formatting
  }
}];

const d = $input.first().json;
const c = d.content_audit || {};
const f = d.formatting_audit || {};
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const list = arr => (arr || []).map(x =>
  `<li>${esc(typeof x === 'string' ? x : (x.improvement || x.text || x.issue || ''))}</li>`
).join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#222">
  <h2 style="color:#0F2A4A">Your resume audit: ${esc(d.role)}</h2>
  <h3>Content audit: ${esc(c.overall_score)}/100 (${esc(c.final_verdict)})</h3>
  <p><b>Biggest strengths</b></p><ul>${list(c.strengths)}</ul>
  <p><b>Biggest gaps</b></p><ul>${list(c.gaps)}</ul>
  <p><b>Top improvements</b></p><ol>${list(c.top_10_improvements)}</ol>
  <h3>Formatting audit: ${esc(f.formatting_score)}/10 (${esc(f.final_verdict)})</h3>
  <p><b>Must fix</b></p><ul>${list(f.critical_issues)}</ul>
  <p><b>Recommendations</b></p><ul>${list(f.recommendations)}</ul>
  <p style="color:#888;font-size:12px">This is an automated review.</p>
</div>`;

return [{ json: {
  to: $('Webhook').first().json.body.email,
  subject: `Your resume audit for ${d.role}`,
  html
}}];

